import type { CandleData, ChartLayer, Concept, GlossaryTerm, LevelRole, Lesson, MarkRole, Question, UnitContent } from "../../types";

/** One candle, in price units with 2 decimals (volume optional). */
const k = (o: number, h: number, l: number, c: number, v?: number): CandleData => (v === undefined ? { o, h, l, c } : { o, h, l, c, v });
const mark = (index: number, label: string, at?: "high" | "low", role: MarkRole = "concept"): ChartLayer => ({ kind: "marker", index, label, role, ...(at ? { at } : {}) });
const lvl = (price: number, role: LevelRole, label?: string): ChartLayer => ({ kind: "level", price, role, ...(label ? { label } : { chip: false }) });
const seg = (pts: [number, number][], role: MarkRole = "concept", label?: string, dashed?: boolean): ChartLayer => ({
  kind: "path",
  points: pts.map(([index, price]) => ({ index, price })),
  role,
  ...(label ? { label } : {}),
  ...(dashed ? { dashed } : {}),
});

/*
 * How every series and statistic below was made (seeded scripts, node; same seed, same numbers):
 * - R0 candles: Gaussian random walk, 12 sub-steps per candle, σ 0.30 per candle, open = previous close, start 100.00.
 * - 3.4.1 HS: a head-and-shoulders detector (zigzag pivots 1.00, shoulders within 30% of the head's height, first close
 *   under the neckline within 20 candles of the right shoulder) on 10,000 R0 paths of 200 candles (seed 3401): 3,091
 *   patterns; 50.0% closed lower 10 candles after the break, against 49.7% for all 1,700,000 candles. HS is path 81.
 * - 3.4.2 test (seeds 3421/3422, 2,000 paths × 1,000 candles): anchor rule fixed first (fractal swings, 5 candles each
 *   side; the last finished leg of at least 6 ATR); event = first candle within 0.1 ATR of a level; outcome = 1 ATR back in
 *   the leg's direction before 1 ATR on, within 20 candles. R0: Fibonacci 38.2/50/61.8% 48.1% (37,236 events), control
 *   41/55/67% 48.0% (33,773), difference 0.2 ± 0.7. "Fib watchers" 30% (a simulator setting: extra order flow against the
 *   pullback within 0.05 ATR of the levels): 56.2% (35,081) vs 55.1% (30,290), difference 1.0 ± 0.8.
 * - 3.4.4 ALT: R0 path 9399 (seed 3441, 40,000 paths, zigzag 1.20), shifted so its low is 100.00. 204 paths had the same
 *   shape (high > lower high > price > higher low > low, legs contracting); price broke the recent high before the recent
 *   low in 140 (68.6%), against 72.2% from the distances alone.
 * - 3.4.5: on R0 from 95.30, price reached 98.00 before 94.40 in 25.6% of 20,000 paths (seed 3451). WY_RANGE and
 *   WY_LIVE are drawn through fixed pivots (generator seeds 348, 346).
 * - 3.4.6: harmonic detector (zigzag 1.00; Gartley, Bat, Butterfly, Crab ratios, tolerance relative) on 400 R0 charts of
 *   2,000 candles (seed 3461): 29, 100, 283 and 1,026 detections at ±1%, ±2.5%, ±5%, ±10%. Reversal at D (seeds 3462/3463,
 *   3,000 charts each): R0 Gartley D 44.4% (3,156) vs random depth 0.60–0.95 45.1% (3,200); R2 (mean-reverting,
 *   θ 0.05 toward 100) 51.8% (4,286) vs 51.8% (4,322).
 * - 3.4.7 (300 runs × 2,000 candles, long and short, 1 unit, spread 0.10, commission 0.05% per fill, stop = Kijun ∓ 0.10,
 *   exit on a close through Kijun): per 1,000 candles, R1 (drift ±0.06 per candle, segments of ~200) full system 15.7 vs
 *   Kijun cross 16.8; R2 −11.9 vs −37.8; R0 −2.5 vs −16.2. Trades per 1,000 candles: 10.4/18.6/14.1 vs 64.8/121.7/95.6.
 *   Grid on R1: 14.9, 15.7, 16.3, 16.1, 16.3, 15.8. One R0 sample (seed 11): −2.3, 1.3, −1.1, −1.6, −1.0, −1.2.
 *   ICHI: seed 10, one full-system long (entry candle 35) and its exit (candle 67), lines as of each candle.
 * - 3.4.8 NOISE: R0 seed 3481; strongest periodogram cycle (linear detrend, periods 8 to n/2) of the last 64, 128 and
 *   256 candles: 16.0, 42.7 and 128.0. In 3,000 R0 windows of 128 candles, the top cycle was 64 or 42.7 candles 82.2% of
 *   the time. Calendar test (20 × 252 days, σ 1%): R13 adds 0.25% on each month's first day. R13: month start +0.21%
 *   ± 0.12 (240 days), full moon −0.03% ± 0.13 (247); R0: −0.01% ± 0.13 and −0.05% ± 0.14.
 * Sizes: commission 0.05% per fill, rounded up to the cent; 52 units at 101.70/99.90 lose 98.85, 53 lose 100.75;
 * 125 units at 106.40/105.71 lose 99.51, 126 lose 100.31.
 */

